from pathlib import Path

DASH=Path('js/modules/dashboard.js')
CSS=Path('css/design-system.css')
TEST=Path('tests/dashboard-card-routes-smoke.test.js')
SW=Path('service-worker.js')

dash=DASH.read_text(encoding='utf-8')
oldlet="let mounted=false,unsubs=[],reminderShown=false,trialTimer=null;"
newlet="let mounted=false,unsubs=[],reminderShown=false,trialTimer=null,calendarSelectedDay='';"
if oldlet not in dash and newlet not in dash: raise SystemExit('dashboard state declaration not found')
dash=dash.replace(oldlet,newlet,1)

start=dash.find('function calendarSection(){')
end=dash.find('\nfunction socialSection',start)
if start<0 or end<0: raise SystemExit('calendarSection boundaries not found')
new="""function calendarLessons(d){const tid=teacherId(),name=dayName(d);if(!tid)return[];return arr('dersProgrami').filter(x=>x.ogretmenId===tid&&sameDay(x.gun,name)).sort(sortHour)}
function calendarIso(d){const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`}
function calendarSection(){if(isAdmin())return'';const base=new Date(),today=new Date(isoToday()+'T00:00:00'),diff=(base.getDay()+6)%7,mon=new Date(base);mon.setDate(base.getDate()-diff);mon.setHours(0,0,0,0);const dates=Array.from({length:7},(_,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);return d}),personal=collectReminders(6).filter(x=>x.gunFarki>=0&&x.gunFarki<=6),personalCounts=Array.from({length:7},(_,i)=>personal.filter(x=>x.gunFarki===i).length),todayKey=isoToday();let selected=calendarSelectedDay&&dates.some(d=>calendarIso(d)===calendarSelectedDay)?calendarSelectedDay:todayKey;if(!dates.some(d=>calendarIso(d)===selected))selected=calendarIso(dates[0]);const selectedDate=dates.find(d=>calendarIso(d)===selected)||dates[0],selectedOffset=Math.round((selectedDate-today)/86400000),lessons=calendarLessons(selectedDate),reminders=selectedOffset>=0&&selectedOffset<=6?personal.map((r,i)=>({...r,_calendarIndex:i})).filter(r=>r.gunFarki===selectedOffset):[],calendarIcon='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M16 3v4M8 3v4M3 11h18\"/></svg>';const dayButtons=dates.map((d,i)=>{const key=calendarIso(d),offset=Math.round((d-today)/86400000),count=offset>=0&&offset<=6?personalCounts[offset]:0,has=count>0||calendarLessons(d).length>0;return `<button type=\"button\" class=\"kh-day ${key===selected?'today':''} ${has?'has':''}\" data-dash-calendar-day=\"${key}\">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'][i]}<b>${d.getDate()}</b></button>`}).join('');const agenda=[...lessons.map(x=>`<button type=\"button\" class=\"kh-row\" data-dash-route=\"academic\" data-dash-page=\"schedule\" data-dash-title=\"Ders Programı\"><div class=\"kh-row-main\"><b>${esc(classLabel(x))} · ${esc(lessonLabel(x))}</b><small>${x.saat?`${esc(String(x.saat))}. ders`:'Ders programı'}</small></div><span class=\"kh-calendar-row-icon\" aria-hidden=\"true\">📘</span></button>`),...reminders.map(r=>`<button type=\"button\" class=\"kh-row\" data-dash-calendar-reminder=\"${r._calendarIndex}\"><div class=\"kh-row-main\"><b>${esc(r.baslik)}</b><small>${esc(r.altBaslik||'Tüm gün')}</small></div><span class=\"kh-calendar-row-icon\" aria-hidden=\"true\">🔔</span></button>`)].join('');return `<section class=\"kh-section\" data-home-section=\"calendar\"><div class=\"kh-section-head\"><div class=\"kh-section-title\">${calendarIcon}<span>Takvim</span></div><button type=\"button\" class=\"kh-more\" data-dash-route=\"communication\" data-dash-page=\"calendar\" data-dash-title=\"Takvim\">${esc(base.toLocaleDateString('tr-TR',{month:'long',year:'numeric'}))} ›</button></div><div class=\"kh-card\"><div class=\"kh-calendar\">${dayButtons}</div><div class=\"kh-agenda-title\">${esc(selectedDate.toLocaleDateString('tr-TR',{day:'numeric',month:'long',weekday:'long'}).toLocaleUpperCase('tr'))}</div>${agenda||'<div class=\"kh-empty\">Bu gün için kayıt bulunmuyor.</div>'}</div></section>`}"""
dash=dash[:start]+new+dash[end:]

needle="  root.querySelector('[data-dash-quick-note]')?.addEventListener('click',()=>window.ShellUI?.openQuickNote?.())"
insert="""  root.querySelectorAll('[data-dash-calendar-day]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();calendarSelectedDay=btn.dataset.dashCalendarDay||'';requestAnimationFrame(render)}));
  root.querySelectorAll('[data-dash-calendar-reminder]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();collectReminders(6)[Number(btn.dataset.dashCalendarReminder)]?.git?.()}));
"""+needle
if needle not in dash: raise SystemExit('bindPresentation insertion point not found')
dash=dash.replace(needle,insert,1)
DASH.write_text(dash,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
marker='/* LEGACY INTERACTIVE CALENDAR — REFERENCE PORT */'
block='''\n\n/* LEGACY INTERACTIVE CALENDAR — REFERENCE PORT */\n.ka-home .kh-section[data-home-section="calendar"]{display:flex;flex-direction:column;gap:8px}\n.ka-home .kh-section[data-home-section="calendar"] .kh-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px}\n.ka-home .kh-section[data-home-section="calendar"] .kh-section-title{display:flex;align-items:center;gap:8px;min-width:0;font-size:15.5px;font-weight:900;color:var(--ka-text)}\n.ka-home .kh-section[data-home-section="calendar"] .kh-section-title>svg{width:19px;height:19px;flex:none;color:var(--ka-primary)}\n.ka-home .kh-section[data-home-section="calendar"] .kh-more{border:0;background:transparent;color:var(--ka-primary);font:inherit;font-size:10.5px;font-weight:850;padding:6px 2px;white-space:nowrap}\n.ka-home .kh-section[data-home-section="calendar"] .kh-card{overflow:hidden;border:1px solid var(--ka-border);border-radius:20px;background:var(--ka-card-bg);box-shadow:var(--ka-shadow-sm)}\n.ka-home .kh-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;padding:10px}\n.ka-home .kh-day{border:0;background:transparent;border-radius:13px;padding:7px 2px;text-align:center;color:var(--ka-text-muted);font:inherit;font-size:8.5px;cursor:pointer}\n.ka-home .kh-day b{display:block;margin-top:3px;font-size:13px;color:var(--ka-text)}\n.ka-home .kh-day.today{background:var(--ka-primary);color:var(--ka-text-inverse)}\n.ka-home .kh-day.today b{color:var(--ka-text-inverse)}\n.ka-home .kh-day.has:after{content:"";display:block;width:4px;height:4px;border-radius:50%;margin:4px auto 0;background:var(--ka-primary)}\n.ka-home .kh-day.today.has:after{background:var(--ka-text-inverse)}\n.ka-home .kh-agenda-title{padding:0 12px 7px;font-size:9.5px;font-weight:900;color:var(--ka-text-muted)}\n.ka-home .kh-section[data-home-section="calendar"] .kh-row{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:11px 12px;border:0;border-top:1px solid var(--ka-border);background:transparent;color:var(--ka-text);text-align:left;font:inherit;cursor:pointer}\n.ka-home .kh-section[data-home-section="calendar"] .kh-row-main{min-width:0}\n.ka-home .kh-section[data-home-section="calendar"] .kh-row-main b{display:block;font-size:12.5px;line-height:1.28;color:var(--ka-text)}\n.ka-home .kh-section[data-home-section="calendar"] .kh-row-main small{display:block;font-size:10.5px;line-height:1.35;color:var(--ka-text-muted);margin-top:3px}\n.ka-home .kh-calendar-row-icon{width:20px;text-align:center;color:var(--ka-primary)}\n.ka-home .kh-section[data-home-section="calendar"] .kh-empty{padding:14px 12px;text-align:center;color:var(--ka-text-muted);font-size:11px;border-top:1px solid var(--ka-border)}\n'''
if marker not in css: css+=block
CSS.write_text(css,encoding='utf-8')

test=TEST.read_text(encoding='utf-8')
check="""\nassert(dash.includes('function calendarLessons(d)')&&dash.includes('class=\"kh-calendar\"')&&dash.includes('class=\"kh-day '),'Takvim referans Pazartesi-Pazar kh-calendar/kh-day DOM sözleşmesini kullanmalı.');\nassert(dash.includes('data-dash-calendar-day')&&dash.includes('data-dash-calendar-reminder'),'Takvim gün seçimi ve kişisel gündem tıklaması etkileşimli kalmalı.');\nassert(dash.includes("personal=collectReminders(6).filter(x=>x.gunFarki>=0&&x.gunFarki<=6)")&&dash.includes("personal.filter(x=>x.gunFarki===i).length"),'Takvim kişisel 7 günlük reminder motorunu korumalı.');\nassert(!dash.includes('class=\"ka-home-calendar\"'),'Yeni taklit ka-home-calendar renderer içinde kalmamalı.');\nassert(css.includes('LEGACY INTERACTIVE CALENDAR — REFERENCE PORT')&&css.includes('.ka-home .kh-calendar{'),'Takvim legacy geometrisi merkezi design-system içinde kalmalı.');\n// Checkpoint: legacy interactive calendar port.\n"""
if 'LEGACY INTERACTIVE CALENDAR — REFERENCE PORT' not in test: test+=check
TEST.write_text(test,encoding='utf-8')

sw=SW.read_text(encoding='utf-8').replace("const CACHE_ADI='oy-cache-v718';","const CACHE_ADI='oy-cache-v719';")
SW.write_text(sw,encoding='utf-8')

